double boltzmannConstant = 1.380649e-23; // in J/K, but we use reduced units
double kBT = targetTemp; // assuming reduced units where k_B = 1

double collisionProb = 1.0 - std::exp(-collisionFreq * dt);
std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> normalDist(0.0, 1.0);

for (size_t i = 0; i < velocities.size(); ++i) {
    if (std::uniform_real_distribution<double>(0.0, 1.0)(gen) < collisionProb) {
        double sigma_v = std::sqrt(kBT / masses[i]);
        velocities[i].x = normalDist(gen) * sigma_v;
        velocities[i].y = normalDist(gen) * sigma_v;
        velocities[i].z = normalDist(gen) * sigma_v;
    }
}

